import{text}from"node:stream/consumers";async function readStdin(){return text(process.stdin)}function writeOutput(output){process.stdout.write(JSON.stringify(output))}const raw=await readStdin(),event=JSON.parse(raw);if(event.tool_name!==`Agent`)writeOutput({});else{let resume=`resume`in event.tool_input?event.tool_input.resume:void 0;writeOutput(typeof resume==`string`?{hookSpecificOutput:{hookEventName:`PreToolUse`,permissionDecision:`deny`,permissionDecisionReason:[`Blocked: Agent resume call (agent ID: ${resume}).`,`Background agents notify automatically on completion.`,`Do not poll or resume running agents -- wait for the notification.`,`If you need the result now, use TaskOutput to check the agent's status.`].join(` `)}}:{})}export{};